// Storefront API token (already scoped and CORS-allowed for your store)
const STOREFRONT_TOKEN = "eyJ0eXAiOiJKV1QiLCJhbGciOiJFUzI1NiJ9.eyJjaWQiOlsxXSwiY29ycyI6WyJodHRwczovL2RldmVsb3Blci5iaWdjb21tZXJjZS5jb20iXSwiZWF0IjoxNzU3MjUwNDMyLCJpYXQiOjE3NTcwNzc2MzIsImlzcyI6IkJDIiwic2lkIjoxMDEwMDIyNSwic3ViIjoiQkMiLCJzdWJfdHlwZSI6MCwidG9rZW5fdHlwZSI6MX0.YpKrTgsRwGKTeF-8pigtXoLUo99cwqpWR5SBXYwe2l377WmOBmxksUzCUrw6ydX0Aukb8wqyF49fesmixspzrw";
const GRAPHQL_ENDPOINT = '/graphql';

// Full BOM list (SKU + quantity)
const BOM_SKUS = [
  { sku: 'REV-25-3270', qty: 1 },
