  { sku: 'REV-21-2090-PK10', qty: 1 },
  { sku: 'REV-21-2101', qty: 4 },
  { sku: 'REV-21-2102', qty: 1 },
  { sku: 'REV-21-2103', qty: 4 },
  { sku: 'REV-21-2130', qty: 2 },
  { sku: 'REV-21-2161', qty: 3 },
