  { sku: "REV-21-3613", qty: 2 },
  { sku: "REV-21-3617-PK30", qty: 1 },
  { sku: "REV-21-3738-PK25", qty: 1 },
  { sku: "REV-21-3739-PK25", qty: 1 },
  { sku: "REV-21-4048", qty: 1 },
  { sku: "REV-21-4064", qty: 1 },
  { sku: "REV-29-1016-PK100", qty: 1 },
