          onProgress: (done, total, sku, qty, ok) => {
            status.textContent = `${done}/${total} — ${sku} (x${qty}) ${ok ? "✓" : "…"} `;
          },
        });

        status.textContent = "Done. Opening cart…";
        window.location = "/cart.php";
      } finally {
        btn.disabled = false;
        btn.textContent = original;
      }
    });

