        const sku = (dd.textContent || "").trim();
        if (!sku) return;

        const qtyInput = row.querySelector("input.cart-item-qty-input");
        const qty = qtyInput ? parseInt(qtyInput.getAttribute("value") || "0", 10) : 0;
        currentMap[sku] = Number.isFinite(qty) ? qty : 0;
      });

      const ok = [];
      const issues = [];

      Object.keys(bomMap).forEach((sku) => {
        const before = baselineMap[sku] || 0;
        const wantAdd = bomMap[sku] || 0;
        const expected = before + wantAdd;
        const after = currentMap[sku] || 0;

        if (after >= expected) ok.push({ sku, qty: wantAdd });
        else issues.push({ sku, qty: wantAdd, reason: `Short by ${expected - after}` });
      });

      const anchor =
        document.querySelector(".cart") ||
        document.querySelector(".cart-content") ||
        document.querySelector(".page-content") ||
        document.querySelector("main");

      if (!anchor) return;

      const boxId = `starter-bom-cart-message-${set.key}`;
      if (document.getElementById(boxId)) return;

      const box = document.createElement("div");
      box.id = boxId;
      box.style.cssText =
        "margin:16px 0;padding:14px 16px;border:2px solid #f05a28;border-radius:12px;background:#fff;";

      const headline = document.createElement("div");
      headline.style.cssText = "font-weight:800;margin-bottom:8px;";
      headline.textContent = issues.length
        ? `${set.buttonText}: Some items did not fully add (${issues.length}).`
        : `${set.buttonText}: All items were added successfully.`;

      const summary = document.createElement("div");
      summary.style.cssText = "margin-bottom:10px;";
      summary.textContent = `OK: ${ok.length} • Issues: ${issues.length}`;

      box.appendChild(headline);
      box.appendChild(summary);

      if (issues.length) {
        const ul = document.createElement("ul");
        ul.style.cssText = "margin:0;padding-left:18px;";
        issues.slice(0, 200).forEach((s) => {
          const li = document.createElement("li");
          li.textContent = `${s.sku} (wanted +${s.qty}) — ${s.reason}`;
          ul.appendChild(li);
        });
        if (issues.length > 200) {
          const more = document.createElement("div");
          more.style.cssText = "margin-top:8px;font-size:12px;";
          more.textContent = `…and ${issues.length - 200} more.`;
          box.appendChild(more);
        }
        box.appendChild(ul);
      }

      // ✅ dismiss clears ONLY this set’s saved result + last key
      const dismissBtn = document.createElement("button");
      dismissBtn.textContent = "Dismiss";
      dismissBtn.type = "button";
      dismissBtn.style.cssText =
        "margin-top:12px;padding:8px 16px;background:#f05a28;color:#fff;border:none;border-radius:6px;cursor:pointer;font-weight:600;";

      dismissBtn.addEventListener("click", () => {
        box.remove();
        localStorage.removeItem(set.storageKey);
        localStorage.removeItem(LAST_SET_KEY);
      });

      box.appendChild(dismissBtn);

      anchor.insertBefore(box, anchor.firstChild);
    }

    if (window.location.pathname === CART_PATH) {
      document.addEventListener("DOMContentLoaded", renderCartMessageFromBaseline);
      return;
    }

    // -----------------------------
    // PRODUCT PAGE: TWO buttons + add
    // -----------------------------
    if (window.location.pathname !== TARGET_PATH) return;

    function injectButtons() {
      // Create wrapper once
      const heading = document.querySelector("h1.page-heading");
      if (!heading) return false;

      let wrapper = document.getElementById("starter-bom-buttons-wrapper");
      if (!wrapper) {
        wrapper = document.createElement("div");
        wrapper.id = "starter-bom-buttons-wrapper";
        wrapper.style.display = "flex";
        wrapper.style.alignItems = "center";
        wrapper.style.gap = "12px";
        wrapper.style.flexWrap = "wrap";

        heading.parentNode.insertBefore(wrapper, heading);
        wrapper.appendChild(heading);
      }

      SETS.forEach((set) => {
        if (document.getElementById(set.buttonId)) return;

        const btn = document.createElement("button");
        btn.type = "button";
        btn.id = set.buttonId;
        btn.textContent = set.buttonText;

        btn.className = "button";
        btn.style.backgroundColor = "#f05a28";
        btn.style.borderColor = "#f05a28";
        btn.style.color = "#ffffff";
        btn.style.whiteSpace = "nowrap";

        const status = document.createElement("div");
        status.id = set.statusId;
        status.style.cssText = "font-size:12px;opacity:0.9;";
        status.textContent = "";

        btn.addEventListener("click", async () => {
          // Clear old results for THIS set, and set last-run key
          localStorage.removeItem(set.storageKey);
          localStorage.setItem(LAST_SET_KEY, set.key);

          const original = btn.textContent;
          btn.disabled = true;
          btn.textContent = "Adding items…";
          status.textContent = "Starting…";

          try {
            const bomMap = combineBom(set.items);

            // baseline snapshot once
            const baselineHtml = await fetchCartHtmlFresh();
            const baselineMap = parseCartHtmlToQtyMap(baselineHtml);

            localStorage.setItem(
              set.storageKey,
              JSON.stringify({ ts: Date.now(), bomMap, baselineMap })
            );

            const skuQtyPairs = Object.keys(bomMap).map((sku) => ({ sku, qty: bomMap[sku] }));

            await addAllSequentialWithRetry(skuQtyPairs, {
              delayMs: 120,
              maxRetries: 1,
              onProgress: (done, total, sku, qty, ok) => {
                status.textContent = `${done}/${total} — ${sku} (x${qty}) ${ok ? "✓" : "…"} `;
              },
            });

            status.textContent = "Done. Opening cart…";
            window.location = "/cart.php";
          } finally {
            btn.disabled = false;
            btn.textContent = original;
          }
        });

        wrapper.appendChild(btn);
        wrapper.appendChild(status);
      });

      return true;
    }

    document.addEventListener("DOMContentLoaded", injectButtons);
    let tries = 0;
    const t = setInterval(() => {
      tries++;
      if (injectButtons() || tries > 20) clearInterval(t);
    }, 250);
  })();


    (function () {
  function injectTwoButtonMobileCentering() {
    if (document.getElementById("starter-bom-two-btn-center-css")) return;

    const style = document.createElement("style");
    style.id = "starter-bom-two-btn-center-css";
    style.textContent = `
      @media (max-width: 768px) {
        /* The wrapper created by your two-button script */
        #starter-bom-buttons-wrapper {
          display: flex !important;
          flex-direction: column !important;
          align-items: center !important;   /* force centering */
          justify-content: flex-start !important;
          width: 100% !important;
          gap: 6px !important;             /* tighter spacing */
          text-align: center !important;
        }

        /* Keep the H1 centered and full width */
        #starter-bom-buttons-wrapper h1.page-heading {
          width: 100% !important;
          text-align: center !important;
          margin: 0 0 6px 0 !important;
        }

        /* Buttons centered + consistent width */
        #starter-bom-buttons-wrapper button {
          display: block !important;
          width: 100% !important;
          max-width: 360px !important;     /* adjust if you want wider */
          margin: 0 auto !important;       /* keeps centered even if parent styles fight */
        }

        /* Status text centered + tight */
        #starter-bom-buttons-wrapper div[id^="starter-bom-status"] {
          width: 100% !important;
          max-width: 360px !important;
          margin: 2px auto 6px auto !important;
          text-align: center !important;
        }
      }
    `;
    document.head.appendChild(style);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", injectTwoButtonMobileCentering);
  } else {
    injectTwoButtonMobileCentering();
  }
})();

