          { sku: "REV-21-2295-PK2", qty: 2 },
  { sku: "REV-21-3293-PK2", qty: 2 },
  { sku: "REV-11-1850", qty: 1 },
  { sku: "REV-21-3207", qty: 1 },
  { sku: "REV-21-3410", qty: 1 },
  { sku: "REV-21-3540", qty: 2 },
  { sku: "REV-21-3552", qty: 2 },
  { sku: "REV-21-3580", qty: 1 },
  { sku: "REV-21-3610", qty: 4 },
