(function () {
  var param = new URLSearchParams(window.location.search).get('configure-cart');
  if (!param) return;

  // Clean the URL immediately so back-navigation doesn't re-trigger
  var cleanUrl = window.location.pathname + window.location.search.replace(/[?&]configure-cart=[^&]*/g, '').replace(/^&/, '?') + window.location.hash;
  history.replaceState(null, '', cleanUrl || window.location.pathname);

  // Parse BCID:QTY pairs
  var lineItems = [];
  param.split(',').forEach(function (pair) {
    var parts = pair.split(':');
    var id = parseInt(parts[0], 10);
    var qty = parseInt(parts[1], 10) || 1;
    if (id > 0) lineItems.push({ productId: id, quantity: qty });
  });

  if (lineItems.length === 0) return;

  // Loading overlay
  var overlay = document.createElement('div');
  overlay.id = 'rev-cart-overlay';
  overlay.innerHTML = [
    '
',
    '  
',
    '    ',
    '    
Building your cart\u2026',
    '    
Adding ' + lineItems.length + ' item' + (lineItems.length !== 1 ? 's' : '') + ' to your cart.',
    '  ',
    ''
  ].join('');
  document.body.appendChild(overlay);

  function setStatus(msg, sub) {
    var s = document.getElementById('rev-cart-status');
    var b = document.getElementById('rev-cart-sub');
    if (s) s.textContent = msg;
    if (b && sub !== undefined) b.innerHTML = sub;
  }

  // POST to Storefront Cart API (same-origin only)
  fetch('/api/storefront/carts', {
    method: 'POST',
    credentials: 'same-origin',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ lineItems: lineItems })
  })
  .then(function (res) {
    if (!res.ok) throw new Error('Cart API returned ' + res.status);
    return res.json();
  })
  .then(function () {
    setStatus('Cart ready! Redirecting\u2026', '');
    window.location.href = '/cart.php';
  })
  .catch(function (err) {
    console.error('[REV cart builder]', err);
    setStatus(
      'Could not build cart automatically.',
      'Please visit your cart and add items manually, or try refreshing the page.

' + err.message + ''
    );
  });
})();
